def _graver_planche(c):
    nom = "TAHAA75_DECOR"
    if not getattr(c, "_tahaa75_forme_faite", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=FEUILLE_W, uppery=FEUILLE_H)
        p = c.beginPath()
        for contour in _DECOR.split("|"):
            i = 0; n = len(contour)
            while i < n:
                cmd = contour[i]; j = i + 1
                while j < n and contour[j] not in "mlc":
                    j += 1
                v = [float(x) for x in contour[i + 1:j].split(",")]
                if cmd == "m":
                    p.moveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                elif cmd == "l":
                    p.lineTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                else:
                    p.curveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H,
                              v[2] / 1000.0 * FEUILLE_W, FEUILLE_H - v[3] / 1000.0 * FEUILLE_H,
                              v[4] / 1000.0 * FEUILLE_W, FEUILLE_H - v[5] / 1000.0 * FEUILLE_H)
                i = j
            p.close()
        c.drawPath(p, stroke=0, fill=1)
        c.endForm()
        c._tahaa75_forme_faite = True
    return nom


def _poser_decor(c, x0, y0, couleurs):
    nom = _graver_planche(c)
    marge = 0.3 * mm
    for gi, (bord, cadre, cercles) in enumerate(CARTES):
        gx = x0 + bord[0] / 1000.0 * FEUILLE_W - marge
        gl = (bord[1] - bord[0]) / 1000.0 * FEUILLE_W + 2 * marge
        gy = y0 + FEUILLE_H - cadre[1] / 1000.0 * FEUILLE_H - marge
        gh = (cadre[1] - cadre[0]) / 1000.0 * FEUILLE_H + 2 * marge
        c.saveState()
        fen = c.beginPath(); fen.rect(gx, gy, gl, gh)
        c.clipPath(fen, stroke=0, fill=0)
        c.setFillColor(couleurs[gi])
        c.translate(x0, y0)
        c.doForm(nom)
        c.restoreState()


def _gen_carte(rng):
    out = []
    for (bord, cadre, cercles) in CARTES:
        out.append([rng.randint(lo, hi) for (cx, cy, r, lo, hi) in cercles])
    return out


def _dessiner_feuille(c, x0, y0, cartes, series, couleurs, style="eco"):
    police_ch, gris_ch = _style_chiffres(style)
    _poser_decor(c, x0, y0, couleurs)

    def MX(v): return x0 + v / 1000.0 * FEUILLE_W
    def MY(v): return y0 + FEUILLE_H - v / 1000.0 * FEUILLE_H

    for gi, (bord, cadre, cercles) in enumerate(CARTES):
        nums = cartes[gi]
        for (cx, cy, r, lo, hi), val in zip(cercles, nums):
            mx = MX(cx)
            my = MY(cy)
            r_pt = r / 1000.0 * FEUILLE_W
            # ⭐ 06/10 (sceau Maeva : « pousse au maximum ») : le plus gros
            #    chiffre qui tient dans le cercle. On calcule pour « 88 » (le
            #    plus large) : sa boîte doit rentrer dans le disque à 0,90.
            _a = pdfmetrics.stringWidth("88", police_ch, 1.0) / 2.0
            _b = 0.72 / 2.0
            tnum = r_pt * 0.90 / ((_a * _a + _b * _b) ** 0.5)
            if _sec:
                _sec.chiffre_micro(c, val, mx, my - tnum * 0.34, tnum, gris_ch, police_ch, epaisseur=_GRAS_TRAIT)
            else:
                c.setFillColor(gris_ch); c.setFont(police_ch, tnum)
                c.drawCentredString(mx, my - tnum * 0.34, str(val))
        # numero de serie discret, en HAUT a droite (zone vide : le titre
        # est a gauche, le bungalow est en bas a droite)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 5.5)
        c.drawRightString(MX(bord[1]) - 2 * mm, MY(cadre[0]) - 4.2 * mm, "N %05d" % series[gi])
        if _sec:
            try:
                _sec.cadre_micro(c, MX(bord[0]), MY(cadre[1]), MX(bord[1]) - MX(bord[0]),
                                 MY(cadre[0]) - MY(cadre[1]), series[gi], retrait=0.7 * mm)
            except Exception:
                pass


def generer_pdf(nb_cartes=15, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", motif="", page_start=1, **_):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=landscape(A4), pageCompression=1)
    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + CARTES_PAGE - 1) // CARTES_PAGE
    rng = random.Random(760000 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    _deja = set()
    for _p in range(nb_pages):
        if nom_evenement:
            c.setFillColor(colors.black); c.setFont(POLICE, 8)
            c.drawCentredString(PAGE_W / 2, PAGE_H - 4.6 * mm, nom_evenement)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 5.5)
        c.drawRightString(PAGE_W - 5 * mm, PAGE_H - 4.6 * mm, "%03d" % no_page)
        cartes = []
        for _k in range(CARTES_PAGE):
            for _try in range(200):
                carte = [rng.randint(lo, hi) for (b, cad, cercles) in [CARTES[_k]] for (cx, cy, r, lo, hi) in cercles]
                cle = (_k, tuple(carte))
                if cle not in _deja:
                    _deja.add(cle); break
            cartes.append(carte)
        series = [serie + k for k in range(CARTES_PAGE)]
        couleurs = [colors.HexColor(
            couleur_perso if (couleur and couleur_perso)
            else RAINBOW[(s - 1) % len(RAINBOW)] if couleur else TRAIT_NB)
            for s in series]
        _dessiner_feuille(c, MARGE_X, MARGE_Y, cartes, series, couleurs, style=style)
        serie += CARTES_PAGE
        c.showPage()
        no_page += 1
    c.save(); buf.seek(0)
    return buf


if __name__ == "__main__":
    open("test_tahaa75.pdf", "wb").write(generer_pdf(nb_cartes=15, serie_start=1).read())
